function addTaskLine(content, project, status, description) {
  const lines = content.split('\n');

  // Build the new task line
  let newLine;
  if (status === 'Pending') {
    newLine = `    - ${description} (${project})`;
  } else {
    newLine = `    - (${status.toLowerCase()}) ${description} (${project})`;
  }

  // Track state
  let foundProject = false;
  let projectStart = -1;
  let projectEnd = -1;
  let targetStatusLine = -1;       // line of the matching status heading
  let lastTaskInTargetStatus = -1; // line of the last task in the matching status

  // Track all status headings in the target project for ordering
  const statusHeadings = []; // { name, line }
  let lastTaskEnd = -1; // track the last line of content in the project

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // Detect project headings
    const projMatch = line.match(/^ {4}## (.+)/);
    if (projMatch) {
      const projName = projMatch[1].trim();
      const projSlug = projName.split(' ')[0];
      if (projSlug === project) {
        foundProject = true;
        projectStart = i;
        statusHeadings.length = 0;
        lastTaskEnd = -1;
      } else if (foundProject && projectEnd === -1) {
        projectEnd = i;
      }
      continue;
    }

    // Skip lines outside the target project
    if (!foundProject || (projectEnd !== -1 && i >= projectEnd)) continue;

    // Detect status headings within the target project
    const statusMatch = line.match(/^ {4}### (.+)/);
    if (statusMatch) {
      const sname = statusMatch[1].trim();
      statusHeadings.push({ name: sname, line: i });
      if (sname === status) {
        targetStatusLine = i;
      }
      continue;
    }

    // Detect task lines
    const taskMatch = line.match(/^ {4}- /);
    if (taskMatch) {
      // Determine which status section this task belongs to
      let taskStatus = null;
      for (let s = statusHeadings.length - 1; s >= 0; s--) {
        if (statusHeadings[s].line < i) {
          taskStatus = statusHeadings[s].name;
          break;
        }
      }
      if (taskStatus === status) {
        lastTaskInTargetStatus = i;
      }
      lastTaskEnd = i + 1;
    }
  }

  // If the project runs to the end of the file
  if (foundProject && projectEnd === -1) {
    projectEnd = lines.length;
  }

  // Determine where to insert
  const insertLines = [];

  if (targetStatusLine >= 0 && lastTaskInTargetStatus >= 0) {
    // Status section exists with tasks — insert after the last task
    insertLines.push(newLine);
    return spliceLines(lines, lastTaskInTargetStatus + 1, insertLines);
  }

  if (targetStatusLine >= 0) {
    // Status section exists but empty — insert after the heading
    insertLines.push(newLine);
    return spliceLines(lines, targetStatusLine + 1, insertLines);
  }

  // Need to create a new status section
  // Find the right position among existing status headings
  const statusOrder = ['Pending', 'Queued', 'Complete'];
  const targetIdx = statusOrder.indexOf(status);

  let insertAt = projectEnd; // default: end of project

  for (const sh of statusHeadings) {
    const shIdx = statusOrder.indexOf(sh.name);
    if (shIdx > targetIdx) {
      // Insert before this status heading
      insertAt = sh.line;
      break;
    }
  }

  // If the project doesn't exist, create it at the end of the file
  if (!foundProject) {
    // Find the end of the file (trim trailing blank lines)
    let endIdx = lines.length;
    while (endIdx > 0 && lines[endIdx - 1].trim() === '') {
      endIdx--;
    }
    insertAt = endIdx;

    // Add blank line separator before new project
    const before = lines[insertAt - 1];
    if (before !== undefined && before.trim() !== '') {
      insertLines.push('');
    }
    insertLines.push(`    ## ${project}`);
    insertLines.push('');
    insertLines.push(`    ### ${status}`);
    insertLines.push(newLine);
    return spliceLines(lines, insertAt, insertLines);
  }

  // Insert the status heading + task line
  const beforeLine = lines[insertAt - 1];
  if (beforeLine !== undefined && beforeLine.trim() !== '') {
    insertLines.push('');
  }
  insertLines.push(`    ### ${status}`);
  insertLines.push(newLine);

  return spliceLines(lines, insertAt, insertLines);
}

