  let lastTaskInTargetStatus = -1;
  const statusHeadings = [];
  let lastTaskEnd = -1;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const projMatch = line.match(/^ {4}## (.+)/);
    if (projMatch) {
      const projName = projMatch[1].trim();
      const projSlug = projName.split(' ')[0];
      if (projSlug === project) {
